"""Regression test: field validators must not crash when deserialization
produced no data (e.g. a nested field received a value of the wrong type).

See: TypeError: 'NoneType' object is not subscriptable in
``Schema._invoke_field_validators`` (marshmallow 2.20.0).
"""
import pytest

from marshmallow import Schema, fields, validates


class BarSchema(Schema):
    value = fields.String()

    @validates("value")
    def validate_value(self, value):
        pass


class FooSchema(Schema):
    bar = fields.Nested(BarSchema)


@pytest.mark.parametrize("many", [False, True])
def test_field_validator_skipped_when_nested_type_is_invalid(many):
    data = [{"bar": "invalid"}] if many else {"bar": "invalid"}
    schema = FooSchema(many=many)

    errors = schema.validate(data)

    assert errors, "expected nested validation errors to be reported"
    if many:
        assert isinstance(errors, dict)
        assert errors[0]["bar"] == {"_schema": ["Invalid input type."]}
    else:
        assert errors == {"bar": {"_schema": ["Invalid input type."]}}


def test_field_validator_skipped_when_nested_type_is_invalid_load():
    """``load`` must raise a ``ValidationError``, not a ``TypeError``."""
    from marshmallow import ValidationError

    with pytest.raises(ValidationError) as excinfo:
        FooSchema().load({"bar": "invalid"})

    assert excinfo.value.messages == {"bar": {"_schema": ["Invalid input type."]}}


def test_valid_field_validators_still_run():
    """Guarding against ``None`` must not disable normal field validators."""
    calls = []

    class Schema_(Schema):
        value = fields.String()

        @validates("value")
        def validate_value(self, value):
            calls.append(value)

    assert Schema_().load({"value": "ok"}) == {"value": "ok"}
    assert calls == ["ok"]
"}

