"""Regression tests for invalid input passed to a nested field whose schema
defines ``@validates``-decorated field validators.

Previously ``Schema._do_load`` invoked field validators with ``None`` when the
input was not a mapping, raising ``TypeError: 'NoneType' object is not
subscriptable``.
"""
import pytest

from marshmallow import Schema, fields, validates
from marshmallow.exceptions import ValidationError


class BarSchema(Schema):
    value = fields.String()

    @validates('value')
    def validate_value(self, value):
        pass


class FooSchema(Schema):
    bar = fields.Nested(BarSchema)


def test_validate_invalid_nested_value_with_field_validator():
    errors = FooSchema().validate({'bar': 'invalid'})
    assert errors == {'bar': {'_schema': ['Invalid input type.']}}


def test_load_invalid_nested_value_with_field_validator():
    data, errors = FooSchema().load({'bar': 'invalid'})
    assert data == {}
    assert errors == {'bar': {'_schema': ['Invalid input type.']}}


def test_load_invalid_nested_value_with_field_validator_strict():
    with pytest.raises(ValidationError) as excinfo:
        FooSchema(strict=True).load({'bar': 'invalid'})
    assert excinfo.value.messages == {'bar': {'_schema': ['Invalid input type.']}}


def test_load_invalid_nested_many_value_with_field_validator():
    class WrapperSchema(Schema):
        bars = fields.Nested(BarSchema, many=True)

    data, errors = WrapperSchema().load({'bars': 'invalid'})
    assert errors == {'bars': ['Invalid type.']}
"}

