"""Regression tests for ``Dict.getitem`` with unpacked values.

When a dictionary is built by unpacking another mapping, the unpacked value is
not necessarily a dict literal.  It is commonly a name referencing another
dict, or any other (possibly uninferable) expression.  ``Dict.getitem`` must
infer that value before looking the item up instead of raising an
``AttributeError``.
"""

import pytest

from astroid import nodes, parse
from astroid.exceptions import AstroidIndexError


def test_getitem_of_unpacked_name_reference():
    tree = parse(
        """
    X = {
        'A': 'B'
    }

    Y = {
        **X
    }

    KEY = 'A'
    """
    )

    first_dict = tree.body[0].value
    second_dict = tree.body[1].value
    key = tree.body[2].value

    assert first_dict.getitem(key).value == "B"
    assert second_dict.getitem(key).value == "B"


def test_getitem_of_chained_unpacking():
    tree = parse(
        """
    X = {'A': 'B'}
    Y = {**X}
    Z = {**Y, 'C': 'D'}
    """
    )

    x, y, z = (tree.body[i].value for i in range(3))

    assert x.getitem(nodes.Const("A")).value == "B"
    assert y.getitem(nodes.Const("A")).value == "B"
    assert z.getitem(nodes.Const("A")).value == "B"
    assert z.getitem(nodes.Const("C")).value == "D"


def test_getitem_of_uninferable_unpacking_raises_index_error():
    tree = parse(
        """
    def func():
        unknown = some_call()
        return {**unknown}
    """
    )

    dict_node = tree.body[0].body[1].value

    with pytest.raises(AstroidIndexError):
        dict_node.getitem(nodes.Const("A"))


def test_getitem_of_missing_key_in_unpacked_reference_raises_index_error():
    tree = parse(
        """
    X = {'A': 'B'}
    Y = {**X}
    """
    )

    with pytest.raises(AstroidIndexError):
        tree.body[1].value.getitem(nodes.Const("missing"))
"}

