class Foo(Schema):
    bar = fields.Nested(Bar)


class TestNestedInvalidInputWithFieldValidator:
    def test_validate_with_invalid_nested_input_returns_errors(self):
        sch = Foo()
        errors = sch.validate({'bar': 'invalid'})
        assert errors == {'bar': {'_schema': ['Invalid input type.']}}

    def test_load_with_invalid_nested_input_returns_errors(self):
        sch = Foo()
        result = sch.load({'bar': 'invalid'})
        assert result.errors == {'bar': {'_schema': ['Invalid input type.']}}

    def test_valid_nested_input_still_runs_field_validator(self):
