"""Regression tests: Dict.getitem with dict unpacking of non-literal values."""

import pytest

from astroid import AstroidIndexError, Uninferable, parse


def test_getitem_with_unpacked_inferable_dict() -> None:
    """`**X` where X is a Name bound to a dict literal should be inferrable."""
    tree = parse(
        """
    X = {
        'A': 'B'
    }

    Y = {
        **X
    }

    KEY = 'A'
    """
    )
    first_dict = tree.body[0].value
    second_dict = tree.body[1].value
    key = tree.body[2].value

    assert first_dict.getitem(key).value == "B"
    assert second_dict.getitem(key).value == "B"


def test_getitem_with_unpacked_uninferable_value() -> None:
    """An uninferable unpacked value raises AstroidIndexError, not AttributeError."""
    tree = parse(
        """
    Y = {
        **UNKNOWN
    }

    KEY = 'A'
    """
    )
    second_dict = tree.body[0].value
    key = tree.body[1].value

    with pytest.raises(AstroidIndexError):
        second_dict.getitem(key)


def test_getitem_with_unpacked_chained_dicts() -> None:
    """Unpacking a dict that itself unpacks another dict still resolves."""
    tree = parse(
