import pytest

from astroid import nodes, parse
from astroid.exceptions import AstroidIndexError


def _getitem_value(dict_node, key):
    return dict_node.getitem(nodes.Const(key))


def test_getitem_with_name_reference_unpacking() -> None:
    """``{**X}`` where ``X`` refers to a dict literal can be looked up."""
    tree = parse(
        """
X = {'A': 'B'}
Y = {**X}
KEY = 'A'
"""
    )
    first_dict = tree.body[0].value
    second_dict = tree.body[1].value
    key = tree.body[2].value

    assert _getitem_value(first_dict, key.value).value == "B"
    assert _getitem_value(second_dict, key.value).value == "B"


def test_getitem_with_chained_reference_unpacking() -> None:
    """Several layers of ``**`` references resolve to the original value."""
    tree = parse(
        """
X = {'A': 'B'}
Y = {**X}
Z = {**Y}
"""
    )
    y_dict = tree.body[1].value
    z_dict = tree.body[2].value

    assert _getitem_value(y_dict, "A").value == "B"
    assert _getitem_value(z_dict, "A").value == "B"


def test_getitem_with_uninferable_unpacking_raises_index_error() -> None:
    """An uninferable ``**`` value does not leak an ``AttributeError``."""
    tree = parse(
        """
def function(unknown):
    return {**unknown}
"""
    )
    dict_node = tree.body[0].body[0].value

    with pytest.raises(AstroidIndexError):
        dict_node.getitem(nodes.Const("A"))


