@pytest.mark.parametrize('K', [0., 4.0])
def test_physical_n1_grazing_is_zero_array(K):
    aoi = np.array([-100., -90., -45., 0., 45., 90., 100., np.nan])
    expected = np.array([0., 0., 1., 1., 1., 0., 0., np.nan])
    result = _iam.physical(aoi, n=1, K=K)
    assert_allclose(result, expected, atol=1e-12, equal_nan=True)


