import pytest

from sqlfluff.core import Linter


def _lint_l031(sql, dialect="tsql"):
    """Return the L031 violations (rule code, line, pos) for ``sql``."""
    linter = Linter(dialect=dialect)
    return [
        tuple(v)
        for v in linter.lint_string(sql).check_tuples()
        if tuple(v)[0] == "L031"
    ]


@pytest.mark.parametrize(
    "sql",
    [
        # No alias at all.
        "SELECT [hello]\nFROM\n    mytable\n",
        # Same query with an alias used in the select clause and no join.
        "SELECT a.[hello]\nFROM\n    mytable AS a\n",
    ],
)
def test_l031_no_join_no_alias_violation(sql):
    """Single table queries without joins should never raise L031."""
    assert _lint_l031(sql) == []


def test_l031_alias_in_join_still_flagged():
    """An alias used in a real join condition is still reported by L031."""
    sql = (
        "SELECT u.id, c.first_name\n"
        "FROM users as u\n"
        "JOIN customers as c on u.id = c.user_id\n"
    )
    assert _lint_l031(sql) != []
